"""Derive bounded conclusions from preserved actual browser observations."""
from pathlib import Path
import json
S=Path(__file__).resolve().parents[1];load=lambda p:json.loads(p.read_text())
d=load(S/'review/browser-first.json')['operations'];raw=lambda op,key:d[op]['value'][key]['value'];rep=load(S/'review/browser-repair.json');rv=lambda key:rep['repair']['value'][key]['value'];checks=[]
def check(id,observed,expected):checks.append({'id':id,'passed':observed==expected,'observed':observed,'expected':expected})
a=load(S/'outputs/a/decision.json');b=load(S/'outputs/b/decision.json');check('choice-a',a['chosenComponent'],'Select');check('choice-b',b['choice'],'SelectWithSearch')
for arm in ['a','b']:
 base=raw('initial',arm);fill=raw('initial',arm+'Filled');check('unique-ids-'+arm,base['idsUnique'],True);check('four-required-Inputs-'+arm,len([x for x in base['inputs'] if x['component']=='Input' and x['required']]),4);check('real-Input-events-'+arm,[e['detail']['value'] for e in fill['events']],['Ada','Beispiel','ada@example.test','0123 456789']);check('leading-zero-'+arm,fill['phone'],'0123 456789');check('required-missing-'+arm,len(raw('initial',arm+'Empty')['status']),5)
check('native-select-three',raw('initial','a')['selects'][0]['keys'],['','CH','DE','FR'])
check('a-local-success',bool(raw('choice','aSuccess')['status']),True);check('a-edit-clears-success',raw('choice','aEdited')['status'],'')
expected=[o['key'] for o in load(S/'inputs/b.json')['options']];check('thirty-order',raw('choice','opened')['keys'],expected);check('open-search-focus',raw('choice','opened')['focus'],'country-search');check('unknown-no-options',raw('choice','unknown')['options'],0);check('unknown-no-commit',raw('choice','unknownEnter')['key'],'');check('filter-Indien',[o['key'] for o in raw('filter','filtered')['options']],['IN']);check('active-is-not-selected',raw('filter','active')['selected'],[]);check('focus-on-option',raw('filter','active')['focus'],'country-option-IN');check('commit-IN',raw('filter','committed')['key'],'IN');check('commit-restores-trigger',raw('filter','committed')['focus'],'country-trigger');check('b-local-success',bool(raw('filter','success')['status']),True);check('search-keeps-selected-value',raw('filter','separate')['key'],'IN');check('search-keeps-selected-label',raw('filter','separate')['display'],'Indien (+91)');check('shared-prefix-distinct',raw('filter','separate')['options'],['CA','US']);check('escape-retains-IN',raw('filter','retained')['key'],'IN');check('search-clears-stale-success',raw('filter','separate')['status'],'');check('last-option-visible',raw('scroll','last')['visible'],True);check('last-option-actual-key',raw('scroll','last')['key'],'SK');check('scroll-positive',raw('scroll','last')['scrollTop']>0,True);check('navigation-not-commit',raw('scroll','last')['committed'],'IN');check('US-distinct-commit',raw('scroll','shared')['key'],'US');check('b-input-clears-success',raw('scroll','edit')['status'],'');check('SEL2-B01-close-restores-focus',raw('closecheck','after')['focus'].startswith('<button'),True)
repair=[]
for id,actual,expected in [('close-focus',rv('clickClose')['focus'],'country-trigger'),('internal-focus',rv('internal')['focus'],'country-option-IN'),('internal-stays-open',rv('internal')['expanded'],'true'),('commit',rv('commit')['key'],'IN'),('commit-focus',rv('commit')['focus'],'country-trigger'),('escape-focus',rv('escape')['focus'],'country-trigger'),('escape-keeps-value',rv('escape')['key'],'IN'),('escape-clears-query',rv('escape')['query'],''),('leave-closes',rep['tabLeave']['value']['value']['expanded'],'false'),('leave-keeps-value',rep['tabLeave']['value']['value']['key'],'IN')]:repair.append({'id':id,'observed':actual,'expected':expected,'passed':actual==expected})
assert len([c for c in checks if not c['passed']])==1
assert all(c['passed'] for c in repair)
result={'release':False,'scope':'Two policy choices and bounded actual browser observations; counts are checks, not statistical UX accuracy','checks':checks,'firstCheckCount':len(checks),'firstPassed':sum(c['passed'] for c in checks),'retainedFirstIssue':'SEL2-B01','repairChecks':repair,'repairPassed':sum(c['passed'] for c in repair),'primaryChoicesMatch':True,'notChecked':['Full API and SCXML equivalence','Full design geometry/theme/font conformance','Screenreader and real IME','Native platforms','Full independent agent access audit','Usability or statistical generalization']}
(S/'review/results.json').write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n');print(json.dumps({k:v for k,v in result.items() if k in ['firstCheckCount','firstPassed','repairPassed']}))
